// Site-wide facts shared by the page metadata, web manifest, sitemap and
// share image.

export const SITE_NAME = "Ghent Parking";
export const SITE_TAGLINE = "Live free spaces in Ghent's parking garages";
export const SITE_DESCRIPTION =
  "Live parking availability for Ghent — see where to park before you drive.";

// The share image generated by app/opengraph-image.tsx. Pages that set their
// own Open Graph fields must list it again, because a page's `openGraph`
// replaces the layout's as a whole — image included.
export const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${SITE_NAME} — ${SITE_TAGLINE}`,
};

// Colours as plain hex, because the manifest and <meta name="theme-color">
// can't read the CSS variables in globals.css. Keep them in sync with it.
export const BACKGROUND_COLOR = "#1c1d1f"; // --background
export const BRAND_BLUE = "#0072ce"; // the "P" sign in the app icon

// Vercel sets these at build and run time. The production deployment uses
// the project's production domain; previews use their own URL so their share
// images and links resolve to themselves.
export const IS_PRODUCTION = process.env.VERCEL_ENV === "production";

export const SITE_URL =
  IS_PRODUCTION && process.env.VERCEL_PROJECT_PRODUCTION_URL
    ? `https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}`
    : process.env.VERCEL_URL
      ? `https://${process.env.VERCEL_URL}`
      : "http://localhost:3000";
